import re, glob

def extract_img_tags(txt):
    tags = []
    for m in re.finditer(r'<img\b', txt):
        i = m.start()
        j = i
        n = len(txt)
        while j < n:
            if txt.startswith('{{', j):
                end = txt.find('}}', j+2)
                j = end+2 if end != -1 else n
            elif txt.startswith('{!!', j):
                end = txt.find('!!}', j+3)
                j = end+3 if end != -1 else n
            elif txt[j] == '>':
                break
            else:
                j += 1
        tags.append((i, txt[i:j+1]))
    return tags

files = sorted(glob.glob('resources/views/**/*.blade.php', recursive=True))
total = 0
for f in files:
    if '/vendor/' in f:
        continue
    txt = open(f, encoding='utf-8', errors='replace').read()
    for pos, tag in extract_img_tags(txt):
        # strip blade exprs before checking attrs
        clean = re.sub(r'\{\{.*?\}\}|\{!!.*?!!\}', 'X', tag, flags=re.S)
        has_w = re.search(r'\bwidth\s*=', clean)
        has_h = re.search(r'\bheight\s*=', clean)
        if not (has_w and has_h):
            line = txt.count('\n', 0, pos) + 1
            total += 1
            print(f'{f}:{line}')
            print('   ', ' '.join(tag.split())[:220])
print(f'\nTOTALE: {total} img senza width/height')
