    for m in re.finditer(r'<img\b', txt):
        i = m.start(); j = i; n = len(txt)
        while j < n:
            if txt.startswith('{{', j):
                e = txt.find('}}', j+2); j = e+2 if e != -1 else n
            elif txt.startswith('{!!', j):
                e = txt.find('!!}', j+3); j = e+3 if e != -1 else n
            elif txt[j] == '>':
                break
            else:
                j += 1
        tags.append((i, txt[i:j+1]))
    return tags

files = sorted(glob.glob('resources/views/vendor/**/*.blade.php', recursive=True))
for f in files:
    txt = open(f).read()
    for pos, tag in extract_img_tags(txt):
        clean = re.sub(r'\{\{.*?\}\}|\{!!.*?!!\}', 'X', tag, flags=re.S)
        ok = re.search(r'\bwidth\s*=', clean) and re.search(r'\bheight\s*=', clean)
        line = txt.count('\n', 0, pos) + 1
        print(('OK  ' if ok else 'MISS'), f'{f}:{line}', ' '.join(tag.split())[:150])
